import { NextRequest, NextResponse } from "next/server";
import getClientPromise from "@/lib/mongodb";

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { name, phone, address, product, quantity } = body;

    if (!name || !phone || !address || !product || !quantity) {
      return NextResponse.json(
        { success: false, message: "Sila isi semua ruangan." },
        { status: 400 }
      );
    }

    const client = await getClientPromise();
    const db = client.db("ecommerce");
    const orders = db.collection("orders");

    const order = {
      name,
      phone,
      address,
      product,
      quantity,
      createdAt: new Date(),
    };

    await orders.insertOne(order);

    return NextResponse.json(
      { success: true, message: "Pesanan berjaya disimpan!" },
      { status: 201 }
    );
  } catch (error) {
    console.error("Order error:", error);
    return NextResponse.json(
      { success: false, message: "Ralat pelayan. Sila cuba lagi." },
      { status: 500 }
    );
  }
}

