import { NextRequest, NextResponse } from "next/server";

const ADMIN_PASSWORD = process.env.ADMIN_PASSWORD || "admin123";

export async function POST(request: NextRequest) {
  const body = await request.json();
  const { password } = body;

  if (password === ADMIN_PASSWORD) {
    const token = Buffer.from(`admin:${Date.now()}`).toString("base64");
    return NextResponse.json({ success: true, token });
  }

  return NextResponse.json(
    { success: false, message: "Kata laluan salah." },
    { status: 401 }
  );
}

import { NextRequest, NextResponse } from "next/server";
import getClientPromise from "@/lib/mongodb";

export async function GET(request: NextRequest) {
  try {
    const auth = request.headers.get("authorization") || "";
    if (!auth.startsWith("Bearer ")) {
      return NextResponse.json({ success: false, message: "Unauthorized" }, { status: 401 });
    }

    const client = await getClientPromise();
    const db = client.db("ecommerce");
    const orders = await db
      .collection("orders")
      .find({})
      .sort({ createdAt: -1 })
      .limit(100)
      .toArray();

    return NextResponse.json({ success: true, orders });
  } catch (error: any) {
    return NextResponse.json(
      { success: false, message: error.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import getClientPromise from "@/lib/mongodb";

async function checkAuth(request: NextRequest) {
  const auth = request.headers.get("authorization") || "";
  return auth.startsWith("Bearer ");
}

export async function GET() {
  try {
    const client = await getClientPromise();
    const db = client.db("ecommerce");
    const settings = await db.collection("settings").findOne({ key: "site" });

    return NextResponse.json({
      success: true,
      settings: settings?.value || getDefaults(),
    });
  } catch (error: any) {
    return NextResponse.json({ success: false, message: error.message }, { status: 500 });
  }
}

export async function POST(request: NextRequest) {
  if (!(await checkAuth(request))) {
    return NextResponse.json({ success: false, message: "Unauthorized" }, { status: 401 });
  }

  try {
    const body = await request.json();
    const client = await getClientPromise();
    const db = client.db("ecommerce");

    await db.collection("settings").updateOne(
      { key: "site" },
      { $set: { key: "site", value: body } },
      { upsert: true }
    );

    return NextResponse.json({ success: true, message: "Tetapan disimpan!" });
  } catch (error: any) {
    return NextResponse.json({ success: false, message: error.message }, { status: 500 });
  }
}

