}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";

export default function AdminLoginPage() {
  const router = useRouter();
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    try {
      const res = await fetch("/api/admin/auth", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password }),
      });
      const data = await res.json();

      if (data.success) {
        localStorage.setItem("admin_token", data.token);
        router.push("/admin/dashboard");
      } else {
        setError("Kata laluan salah.");
      }
    } catch {
      setError("Ralat rangkaian.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center px-4 bg-gray-100">
      <div className="w-full max-w-sm">
        <h1 className="text-2xl font-bold text-center text-gray-900 mb-8">
          🔐 Admin Login
        </h1>
        <form
          onSubmit={handleLogin}
          className="bg-white rounded-2xl shadow-md p-8 space-y-4"
        >
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">
              Kata Laluan
            </label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="••••••"
              className="w-full border border-gray-200 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
              autoFocus
            />
          </div>
          {error && (
            <div className="bg-red-50 text-red-600 text-sm rounded-xl px-4 py-3">
              {error}
            </div>
          )}
          <button
            type="submit"
            disabled={loading}
            className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl hover:bg-blue-700 transition-colors disabled:opacity-50"
          >
            {loading ? "Log masuk..." : "Log Masuk"}
          </button>
        </form>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";

type Order = {
  _id: string;
  name: string;
  phone: string;
  address: string;
  product: string;
  quantity: number;
  createdAt: string;
};

type Settings = {
  product: {
    name: string;
    price: number;
    description: string;
    benefits: string[];
  };
  landing: {
    badge: string;
    headline: string;
    subtext: string;
    finalHeadline: string;
    finalSubtext: string;
  };
  whatsapp: string;
};

export default function AdminDashboard() {
  const router = useRouter();
  const [token, setToken] = useState("");
  const [tab, setTab] = useState<"orders" | "product" | "landing">("orders");
  const [orders, setOrders] = useState<Order[]>([]);
  const [settings, setSettings] = useState<Settings | null>(null);
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState("");

  useEffect(() => {
    const t = localStorage.getItem("admin_token");
    if (!t) {
      router.push("/admin");
      return;
    }
    setToken(t);
    fetchOrders(t);
    fetchSettings(t);
  }, []);

  const headers = { Authorization: `Bearer ${token}` };

  const fetchOrders = async (t?: string) => {
    try {
      const res = await fetch("/api/admin/orders", {
        headers: { Authorization: `Bearer ${t || token}` },
      });
      const data = await res.json();
      if (data.success) setOrders(data.orders);
    } catch {}
  };

  const fetchSettings = async (t?: string) => {
    try {
      const res = await fetch("/api/admin/settings", {
        headers: { Authorization: `Bearer ${t || token}` },
      });
      const data = await res.json();
      if (data.success) setSettings(data.settings);
    } catch {}
  };

  const saveSettings = async () => {
    if (!settings) return;
    setLoading(true);
    setMsg("");
    try {
      const res = await fetch("/api/admin/settings", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(settings),
      });
      const data = await res.json();
      setMsg(data.message || (data.success ? "Disimpan!" : "Gagal!"));
    } catch {
      setMsg("Ralat rangkaian.");
    } finally {
      setLoading(false);
    }
  };

  const logout = () => {
    localStorage.removeItem("admin_token");
    router.push("/admin");
  };

  const update = (
    section: "product" | "landing",
    field: string,
    value: any
  ) => {
    setSettings((prev) => {
      if (!prev) return prev;
      return {
        ...prev,
        [section]: { ...prev[section], [field]: value },
      };
    });
  };

  const updateBenefit = (index: number, value: string) => {
    setSettings((prev) => {
      if (!prev) return prev;
      const benefits = [...prev.product.benefits];
      benefits[index] = value;
      return { ...prev, product: { ...prev.product, benefits } };
    });
  };

  if (!settings) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        Loading...
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100">
      {/* Header */}
      <header className="bg-white shadow-sm border-b sticky top-0 z-10">
        <div className="max-w-6xl mx-auto px-4 py-3 flex items-center justify-between">
          <h1 className="text-xl font-bold text-gray-900">⚙️ Admin Panel</h1>
          <button
            onClick={logout}
            className="text-sm text-red-600 hover:text-red-800 font-medium"
          >
            Log Keluar
          </button>
        </div>
      </header>

      {/* Tabs */}
      <div className="max-w-6xl mx-auto px-4 pt-6">
        <div className="flex gap-2 bg-white rounded-xl p-1 shadow-sm border mb-6">
          {(["orders", "product", "landing"] as const).map((t) => (
            <button
              key={t}
              onClick={() => setTab(t)}
              className={`flex-1 py-2 px-4 rounded-lg text-sm font-semibold transition-colors ${
                tab === t
                  ? "bg-blue-600 text-white shadow"
                  : "text-gray-600 hover:bg-gray-100"
              }`}
            >
              {t === "orders" ? "📦 Pesanan" : t === "product" ? "🛍️ Produk" : "📄 Landing Page"}
            </button>
          ))}
        </div>

        {/* Tab: Orders */}
        {tab === "orders" && (
          <div>
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-lg font-bold text-gray-900">
                Senarai Pesanan ({orders.length})
              </h2>
              <button
                onClick={() => fetchOrders()}
                className="text-sm text-blue-600 hover:text-blue-800"
              >
                🔄 Refresh
              </button>
            </div>
            {orders.length === 0 ? (
              <p className="text-gray-500 text-center py-10">Tiada pesanan lagi.</p>
            ) : (
              <div className="space-y-3">
                {orders.map((order) => (
                  <div
                    key={order._id}
                    className="bg-white rounded-xl p-5 shadow-sm border"
                  >
                    <div className="flex justify-between items-start mb-2">
                      <div>
                        <p className="font-bold text-gray-900">{order.name}</p>
                        <p className="text-sm text-gray-500">{order.phone}</p>
                      </div>
                      <span className="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded-full font-semibold">
                        {order.quantity}x
                      </span>
