              <button
                onClick={() => fetchOrders()}
                className="text-sm text-blue-600 hover:text-blue-800"
              >
                 Refresh
              </button>
            </div>
            {orders.length === 0 ? (
              <p className="text-gray-500 text-center py-10">Tiada pesanan lagi.</p>
            ) : (
              <div className="space-y-3">
                {orders.map((order) => (
                  <div
                    key={order._id}
                    className="bg-white rounded-xl p-5 shadow-sm border"
