              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Badge (Hero)
              </label>
              <input
                value={settings.landing.badge}
                onChange={(e) => update("landing", "badge", e.target.value)}
                className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Headline (Hero)
              </label>
              <input
                value={settings.landing.headline}
                onChange={(e) => update("landing", "headline", e.target.value)}
                className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Subtext (Hero)
              </label>
              <textarea
                value={settings.landing.subtext}
                onChange={(e) => update("landing", "subtext", e.target.value)}
                rows={3}
                className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none resize-none"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Final CTA Headline
              </label>
              <input
                value={settings.landing.finalHeadline}
