"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";

type Order = {
  _id: string;
  name: string;
  phone: string;
  address: string;
  product: string;
  quantity: number;
  createdAt: string;
};

type Settings = {
  product: {
    name: string;
    price: number;
    description: string;
    benefits: string[];
  };
  landing: {
    badge: string;
    headline: string;
    subtext: string;
    finalHeadline: string;
    finalSubtext: string;
  };
  whatsapp: string;
};

function formatDate(iso: string) {
  const d = new Date(iso);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(d.getDate())}/${pad(d.getMonth() + 1)}/${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

export default function AdminDashboard() {
  const router = useRouter();
  const [mounted, setMounted] = useState(false);
  const [token, setToken] = useState("");
  const [tab, setTab] = useState<"orders" | "product" | "landing">("orders");
  const [orders, setOrders] = useState<Order[]>([]);
  const [settings, setSettings] = useState<Settings | null>(null);
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState("");

  useEffect(() => {
    const t = localStorage.getItem("admin_token");
    if (!t) {
      router.push("/admin");
      return;
    }
    setToken(t);
    fetchOrders(t);
    fetchSettings(t);
    setMounted(true);
  }, []);

  const fetchOrders = async (t?: string) => {
    try {
      const res = await fetch("/api/admin/orders", {
        headers: { Authorization: `Bearer ${t || token}` },
      });
      const data = await res.json();
      if (data.success) setOrders(data.orders);
    } catch {}
  };

  const fetchSettings = async (t?: string) => {
    try {
      const res = await fetch("/api/admin/settings", {
        headers: { Authorization: `Bearer ${t || token}` },
      });
      const data = await res.json();
      if (data.success) setSettings(data.settings);
    } catch {}
  };

  const saveSettings = async () => {
    if (!settings) return;
    setLoading(true);
    setMsg("");
    try {
      const res = await fetch("/api/admin/settings", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(settings),
      });
      const data = await res.json();
      setMsg(data.message || (data.success ? "Disimpan!" : "Gagal!"));
    } catch {
      setMsg("Ralat rangkaian.");
    } finally {
      setLoading(false);
    }
  };

  const logout = () => {
    localStorage.removeItem("admin_token");
    router.push("/admin");
  };

  const update = (
    section: "product" | "landing",
    field: string,
    value: any
  ) => {
    setSettings((prev) => {
      if (!prev) return prev;
      return {
        ...prev,
        [section]: { ...prev[section], [field]: value },
      };
    });
  };

  const updateBenefit = (index: number, value: string) => {
    setSettings((prev) => {
      if (!prev) return prev;
      const benefits = [...prev.product.benefits];
      benefits[index] = value;
      return { ...prev, product: { ...prev.product, benefits } };
    });
  };

  if (!mounted || !settings) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-100">
        <p className="text-gray-500">Loading...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100">
      <header className="bg-white shadow-sm border-b sticky top-0 z-10">
        <div className="max-w-6xl mx-auto px-4 py-3 flex items-center justify-between">
          <h1 className="text-xl font-bold text-gray-900">⚙️ Admin Panel</h1>
          <button
            onClick={logout}
            className="text-sm text-red-600 hover:text-red-800 font-medium"
          >
            Log Keluar
          </button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 pt-6">
        <div className="flex gap-2 bg-white rounded-xl p-1 shadow-sm border mb-6">
          {(["orders", "product", "landing"] as const).map((t) => (
            <button
              key={t}
              onClick={() => setTab(t)}
              className={`flex-1 py-2 px-4 rounded-lg text-sm font-semibold transition-colors ${
                tab === t
                  ? "bg-blue-600 text-white shadow"
                  : "text-gray-600 hover:bg-gray-100"
              }`}
            >
              {t === "orders" ? "📦 Pesanan" : t === "product" ? "🛍️ Produk" : "📄 Landing Page"}
            </button>
          ))}
        </div>

        {tab === "orders" && (
          <div>
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-lg font-bold text-gray-900">
                Senarai Pesanan ({orders.length})
              </h2>
              <button
                onClick={() => fetchOrders()}
                className="text-sm text-blue-600 hover:text-blue-800"
              >
                🔄 Refresh
              </button>
            </div>
            {orders.length === 0 ? (
              <p className="text-gray-500 text-center py-10">Tiada pesanan lagi.</p>
            ) : (
              <div className="space-y-3">
                {orders.map((order) => (
                  <div
                    key={order._id}
                    className="bg-white rounded-xl p-5 shadow-sm border"
                  >
                    <div className="flex justify-between items-start mb-2">
                      <div>
                        <p className="font-bold text-gray-900">{order.name}</p>
                        <p className="text-sm text-gray-500">{order.phone}</p>
                      </div>
                      <span className="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded-full font-semibold">
                        {order.quantity}x
                      </span>
                    </div>
                    <p className="text-sm text-gray-600 mb-2">{order.address}</p>
                    <div className="flex justify-between items-center">
                      <span className="text-xs text-gray-400">{order.product}</span>
                      <span className="text-xs text-gray-400">
                        {formatDate(order.createdAt)}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {tab === "product" && (
          <div className="bg-white rounded-2xl p-6 shadow-sm border space-y-4">
            <h2 className="text-lg font-bold text-gray-900 mb-4">
              Edit Produk
            </h2>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Nama Produk
              </label>
              <input
                value={settings.product.name}
                onChange={(e) => update("product", "name", e.target.value)}
                className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Harga (RM)
              </label>
              <input
                type="number"
                value={settings.product.price}
                onChange={(e) =>
                  update("product", "price", Number(e.target.value))
                }
                className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Deskripsi
              </label>
              <textarea
                value={settings.product.description}
                onChange={(e) => update("product", "description", e.target.value)}
                rows={3}
                className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none resize-none"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">
                Senarai Kelebihan
              </label>
              {settings.product.benefits.map((b, i) => (
                <input
                  key={i}
                  value={b}
                  onChange={(e) => updateBenefit(i, e.target.value)}
                  className="w-full border rounded-xl px-4 py-2 mb-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                  placeholder={`Kelebihan ${i + 1}`}
                />
              ))}
            </div>
            <button
              onClick={saveSettings}
              disabled={loading}
              className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl hover:bg-blue-700 transition-colors disabled:opacity-50"
            >
              {loading ? "Menyimpan..." : "💾 Simpan Produk"}
            </button>
          </div>
        )}

        {tab === "landing" && (
          <div className="bg-white rounded-2xl p-6 shadow-sm border space-y-4">
            <h2 className="text-lg font-bold text-gray-900 mb-4">
              Edit Landing Page
            </h2>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Badge (Hero)
              </label>
              <input
                value={settings.landing.badge}
                onChange={(e) => update("landing", "badge", e.target.value)}
                className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Headline (Hero)
              </label>
              <input
                value={settings.landing.headline}
                onChange={(e) => update("landing", "headline", e.target.value)}
                className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Subtext (Hero)
              </label>
              <textarea
                value={settings.landing.subtext}
                onChange={(e) => update("landing", "subtext", e.target.value)}
                rows={3}
                className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none resize-none"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Final CTA Headline
              </label>
              <input
                value={settings.landing.finalHeadline}
                onChange={(e) =>
                  update("landing", "finalHeadline", e.target.value)
                }
                className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Final CTA Subtext
              </label>
              <input
                value={settings.landing.finalSubtext}
                onChange={(e) =>
                  update("landing", "finalSubtext", e.target.value)
                }
                className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">
                Nombor WhatsApp
              </label>
              <input
                value={settings.whatsapp}
                onChange={(e) =>
                  setSettings((prev) =>
                    prev ? { ...prev, whatsapp: e.target.value } : prev
                  )
                }
                placeholder="60123456789"
                className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
            </div>
            <button
              onClick={saveSettings}
              disabled={loading}
              className="w-full bg-blue-600 text-white font-bold py-3 rounded-xl hover:bg-blue-700 transition-colors disabled:opacity-50"
            >
              {loading ? "Menyimpan..." : "💾 Simpan Landing Page"}
            </button>
          </div>
        )}

        {msg && (
          <div className="mt-4 text-center text-sm text-green-600 font-medium">
            {msg}
          </div>
        )}
      </div>
    </div>
  );
}

