const fs = require("fs");
const path = require("path");

function size(dir) {
  let s = 0;
  try {
    for (const f of fs.readdirSync(dir)) {
      const p = path.join(dir, f);
      try {
        const st = fs.statSync(p);
        if (st.isDirectory()) s += size(p);
        else s += st.size;
      } catch {}
    }
  } catch {}
  return s;
}

function mb(dir) {
  return (size(dir) / 1024 / 1024).toFixed(1) + " MB";
}

function kb(dir) {
  return (size(dir) / 1024).toFixed(0) + " KB";
}

