"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";

type Product = {
  _id: string;
  name: string;
  price: number;
  description: string;
  benefits: string[];
  image: string;
};

type LandingPage = {
  _id: string;
  name: string;
  slug: string;
  productId: string | null;
  sections: {
    hero: { badge: string; headline: string; subtext: string; ctaText: string; image: string };
    features: { title: string; html: string };
    testimonials: { title: string; html: string };
    cta: { headline: string; subtext: string; html: string };
  };
  whatsapp: string;
  active: boolean;
};

type Tab = "orders" | "products" | "landing";

function formatDate(iso: string) {
  const d = new Date(iso);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(d.getDate())}/${pad(d.getMonth() + 1)}/${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

// ---- PRODUCT FORM ----
function ProductForm({
  initial,
  onSave,
  onCancel,
  loading,
}: {
  initial?: Product;
  onSave: (p: any) => void;
  onCancel: () => void;
  loading: boolean;
}) {
  const [name, setName] = useState(initial?.name || "");
  const [price, setPrice] = useState(initial?.price || 0);
  const [desc, setDesc] = useState(initial?.description || "");
  const [image, setImage] = useState(initial?.image || "");
  const [benefits, setBenefits] = useState<string[]>(initial?.benefits || [""]);

  const addBenefit = () => setBenefits([...benefits, ""]);
  const updateBenefit = (i: number, v: string) => {
    const b = [...benefits]; b[i] = v; setBenefits(b);
  };
  const removeBenefit = (i: number) => setBenefits(benefits.filter((_, j) => j !== i));

  return (
    <div className="bg-white rounded-2xl p-6 shadow-sm border space-y-4">
      <h3 className="font-bold text-lg">{initial ? "Edit Produk" : "Tambah Produk"}</h3>
      <div>
        <label className="block text-sm font-semibold text-gray-700 mb-1">Nama Produk</label>
        <input value={name} onChange={(e) => setName(e.target.value)} className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none" />
      </div>
      <div>
        <label className="block text-sm font-semibold text-gray-700 mb-1">Harga (RM)</label>
        <input type="number" value={price} onChange={(e) => setPrice(Number(e.target.value))} className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none" />
      </div>
      <div>
        <label className="block text-sm font-semibold text-gray-700 mb-1">Deskripsi</label>
        <textarea value={desc} onChange={(e) => setDesc(e.target.value)} rows={3} className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none resize-none" />
      </div>
      <div>
        <label className="block text-sm font-semibold text-gray-700 mb-1">URL Gambar</label>
        <input value={image} onChange={(e) => setImage(e.target.value)} placeholder="/produk.jpg" className="w-full border rounded-xl px-4 py-2 focus:ring-2 focus:ring-blue-500 focus:outline-none" />
      </div>
      <div>
        <label className="block text-sm font-semibold text-gray-700 mb-2">Senarai Kelebihan</label>
        {benefits.map((b, i) => (
          <div key={i} className="flex gap-2 mb-2">
            <input value={b} onChange={(e) => updateBenefit(i, e.target.value)} className="flex-1 border rounded-xl px-3 py-1 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none" placeholder={`Kelebihan ${i + 1}`} />
            <button onClick={() => removeBenefit(i)} className="text-red-500 text-sm px-2">✕</button>
          </div>
        ))}
        <button onClick={addBenefit} className="text-sm text-blue-600 hover:text-blue-800">+ Tambah Kelebihan</button>
      </div>
      <div className="flex gap-3">
        <button onClick={() => onSave({ name, price, description: desc, benefits: benefits.filter(Boolean), image })} disabled={loading} className="bg-blue-600 text-white font-bold py-2 px-6 rounded-xl hover:bg-blue-700 disabled:opacity-50">{loading ? "Menyimpan..." : "Simpan"}</button>
        <button onClick={onCancel} className="text-gray-600 py-2 px-4">Batal</button>
      </div>
    </div>
  );
}

// ---- LANDING PAGE EDITOR ----
function LandingEditor({
  initial,
  products,
  onSave,
  onCancel,
  loading,
