        </div>
        <div>
          <label className="block text-sm font-semibold text-gray-700 mb-1">Slug URL</label>
          <input value={slug} onChange={(e) => setSlug(e.target.value)} className="w-full border rounded-xl px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none" placeholder="landing-utama" />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-semibold text-gray-700 mb-1">Pilih Produk</label>
          <select value={productId} onChange={(e) => setProductId(e.target.value)} className="w-full border rounded-xl px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none">
            <option value="">-- Tiada --</option>
            {products.map((p) => (
              <option key={p._id} value={p._id}>{p.name} (RM{p.price})</option>
            ))}
          </select>
        </div>
        <div>
          <label className="block text-sm font-semibold text-gray-700 mb-1">WhatsApp</label>
          <input value={whatsapp} onChange={(e) => setWhatsapp(e.target.value)} className="w-full border rounded-xl px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none" />
        </div>
      </div>

      <label className="flex items-center gap-2 text-sm">
        <input type="checkbox" checked={active} onChange={(e) => setActive(e.target.checked)} />
        <span className="font-semibold">Aktif (paparkan di / )</span>
      </label>

      {/* HERO */}
      <details open className="border rounded-xl p-4">
        <summary className="font-bold cursor-pointer">Hero Section</summary>
        <div className="space-y-3 mt-3">
          <div>
            <label className="block text-xs font-semibold text-gray-500 mb-1">Badge</label>
            <input value={hero.badge} onChange={(e) => setHero({ ...hero, badge: e.target.value })} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none" />
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-500 mb-1">Headline (HTML)</label>
            <textarea value={hero.headline} onChange={(e) => setHero({ ...hero, headline: e.target.value })} rows={2} className="w-full border rounded-lg px-3 py-2 text-sm font-mono focus:ring-2 focus:ring-blue-500 focus:outline-none resize-none" />
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-500 mb-1">Subtext (HTML)</label>
            <textarea value={hero.subtext} onChange={(e) => setHero({ ...hero, subtext: e.target.value })} rows={2} className="w-full border rounded-lg px-3 py-2 text-sm font-mono focus:ring-2 focus:ring-blue-500 focus:outline-none resize-none" />
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-500 mb-1">Teks Butang CTA</label>
            <input value={hero.ctaText} onChange={(e) => setHero({ ...hero, ctaText: e.target.value })} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none" />
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-500 mb-1">URL Gambar Hero</label>
            <input value={hero.image} onChange={(e) => setHero({ ...hero, image: e.target.value })} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none" />
          </div>
        </div>
      </details>

      {/* FEATURES */}
      <details className="border rounded-xl p-4">
        <summary className="font-bold cursor-pointer">Features Section</summary>
        <div className="space-y-3 mt-3">
          <div>
            <label className="block text-xs font-semibold text-gray-500 mb-1">Tajuk</label>
            <input value={features.title} onChange={(e) => setFeatures({ ...features, title: e.target.value })} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none" />
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-500 mb-1">Kandungan (HTML)</label>
            <textarea value={features.html} onChange={(e) => setFeatures({ ...features, html: e.target.value })} rows={4} className="w-full border rounded-lg px-3 py-2 text-sm font-mono focus:ring-2 focus:ring-blue-500 focus:outline-none resize-none" />
          </div>
        </div>
      </details>

      {/* TESTIMONIALS */}
      <details className="border rounded-xl p-4">
        <summary className="font-bold cursor-pointer">Testimonials Section</summary>
        <div className="space-y-3 mt-3">
          <div>
            <label className="block text-xs font-semibold text-gray-500 mb-1">Tajuk</label>
            <input value={testimonials.title} onChange={(e) => setTestimonials({ ...testimonials, title: e.target.value })} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none" />
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-500 mb-1">Kandungan (HTML)</label>
            <textarea value={testimonials.html} onChange={(e) => setTestimonials({ ...testimonials, html: e.target.value })} rows={4} className="w-full border rounded-lg px-3 py-2 text-sm font-mono focus:ring-2 focus:ring-blue-500 focus:outline-none resize-none" />
          </div>
        </div>
      </details>

      {/* CTA */}
      <details className="border rounded-xl p-4">
        <summary className="font-bold cursor-pointer">CTA Section</summary>
        <div className="space-y-3 mt-3">
          <div>
            <label className="block text-xs font-semibold text-gray-500 mb-1">Headline</label>
            <input value={cta.headline} onChange={(e) => setCta({ ...cta, headline: e.target.value })} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none" />
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-500 mb-1">Subtext</label>
            <input value={cta.subtext} onChange={(e) => setCta({ ...cta, subtext: e.target.value })} className="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 focus:outline-none" />
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-500 mb-1">Kandungan Tambahan (HTML)</label>
