}

// ---- MAIN DASHBOARD ----
export default function AdminDashboard() {
  const router = useRouter();
  const [mounted, setMounted] = useState(false);
  const [token, setToken] = useState("");
  const [tab, setTab] = useState<Tab>("orders");
  const [orders, setOrders] = useState<any[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [pages, setPages] = useState<LandingPage[]>([]);
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState("");
  const [showProductForm, setShowProductForm] = useState(false);
  const [editProduct, setEditProduct] = useState<Product | null>(null);
  const [showLandingEditor, setShowLandingEditor] = useState(false);
  const [editLanding, setEditLanding] = useState<LandingPage | null>(null);

  useEffect(() => {
    const t = localStorage.getItem("admin_token");
    if (!t) { router.push("/admin"); return; }
    setToken(t);
    fetchOrders(t);
    fetchProducts();
    fetchLandingPages();
    setMounted(true);
  }, []);

  const h = (tkn?: string) => ({ Authorization: `Bearer ${tkn || token}` });

  const fetchOrders = async (t?: string) => {
    try {
      const res = await fetch("/api/admin/orders", { headers: h(t) });
      const data = await res.json();
      if (data.success) setOrders(data.orders);
    } catch {}
  };

  const fetchProducts = async () => {
    try {
      const res = await fetch("/api/admin/products");
      const data = await res.json();
      if (data.success) setProducts(data.products);
    } catch {}
  };

  const fetchLandingPages = async () => {
    try {
      const res = await fetch("/api/admin/landing-pages");
      const data = await res.json();
      if (data.success) setPages(data.pages);
    } catch {}
  };

  const saveProduct = async (body: any) => {
    setLoading(true); setMsg("");
    try {
      const url = editProduct
        ? `/api/admin/products/${editProduct._id}`
        : "/api/admin/products";
      const method = editProduct ? "PUT" : "POST";
      const res = await fetch(url, { method, headers: { ...h(), "Content-Type": "application/json" }, body: JSON.stringify(body) });
      const data = await res.json();
      if (data.success) {
        setMsg("Produk disimpan!");
        setShowProductForm(false);
        setEditProduct(null);
        fetchProducts();
      } else setMsg(data.message || "Gagal");
    } catch { setMsg("Ralat rangkaian."); }
    finally { setLoading(false); }
  };

  const deleteProduct = async (id: string) => {
    if (!confirm("Padam produk ini?")) return;
    try {
      const res = await fetch(`/api/admin/products/${id}`, { method: "DELETE", headers: h() });
      const data = await res.json();
      if (data.success) fetchProducts();
      setMsg(data.message || "");
    } catch { setMsg("Ralat."); }
  };

  const saveLanding = async (body: any) => {
    setLoading(true); setMsg("");
    try {
      const url = editLanding
        ? `/api/admin/landing-pages/${editLanding._id}`
        : "/api/admin/landing-pages";
      const method = editLanding ? "PUT" : "POST";
      const res = await fetch(url, { method, headers: { ...h(), "Content-Type": "application/json" }, body: JSON.stringify(body) });
      const data = await res.json();
      if (data.success) {
        setMsg("Landing page disimpan!");
        setShowLandingEditor(false);
        setEditLanding(null);
        fetchLandingPages();
      } else setMsg(data.message || "Gagal");
    } catch { setMsg("Ralat rangkaian."); }
    finally { setLoading(false); }
  };

  const deleteLanding = async (id: string) => {
    if (!confirm("Padam landing page ini?")) return;
    try {
      await fetch(`/api/admin/landing-pages/${id}`, { method: "DELETE", headers: h() });
      fetchLandingPages();
      setMsg("Dipadam.");
    } catch { setMsg("Ralat."); }
  };

  const setActive = async (page: LandingPage) => {
    try {
      const res = await fetch(`/api/admin/landing-pages/${page._id}`, {
        method: "PUT",
        headers: { ...h(), "Content-Type": "application/json" },
        body: JSON.stringify({ ...page, active: true }),
      });
      if ((await res.json()).success) fetchLandingPages();
    } catch {}
  };

  const logout = () => { localStorage.removeItem("admin_token"); router.push("/admin"); };

  if (!mounted) {
    return <div className="min-h-screen flex items-center justify-center bg-gray-100"><p className="text-gray-500">Loading...</p></div>;
  }

  return (
    <div className="min-h-screen bg-gray-100">
      <header className="bg-white shadow-sm border-b sticky top-0 z-10">
        <div className="max-w-6xl mx-auto px-4 py-3 flex items-center justify-between">
          <h1 className="text-xl font-bold text-gray-900">Admin Panel</h1>
          <button onClick={logout} className="text-sm text-red-600 hover:text-red-800 font-medium">Log Keluar</button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 pt-6">
        {/* Tabs */}
        <div className="flex gap-2 bg-white rounded-xl p-1 shadow-sm border mb-6">
          {(["orders", "products", "landing"] as const).map((t) => (
            <button key={t} onClick={() => setTab(t)} className={`flex-1 py-2 px-4 rounded-lg text-sm font-semibold ${tab === t ? "bg-blue-600 text-white shadow" : "text-gray-600 hover:bg-gray-100"}`}>
              {t === "orders" ? "Pesanan" : t === "products" ? "Produk" : "Landing Pages"}
            </button>
          ))}
        </div>

        {msg && <div className="mb-4 text-center text-sm text-green-600 font-medium">{msg}</div>}

        {/* ---- ORDERS TAB ---- */}
        {tab === "orders" && (
          <div>
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-lg font-bold text-gray-900">Senarai Pesanan ({orders.length})</h2>
              <button onClick={() => fetchOrders()} className="text-sm text-blue-600 hover:text-blue-800">Refresh</button>
            </div>
            {orders.length === 0 ? (
              <p className="text-gray-500 text-center py-10">Tiada pesanan lagi.</p>
            ) : (
              <div className="space-y-3">
                {orders.map((o: any) => (
                  <div key={o._id} className="bg-white rounded-xl p-5 shadow-sm border">
                    <div className="flex justify-between items-start mb-2">
                      <div><p className="font-bold text-gray-900">{o.name}</p><p className="text-sm text-gray-500">{o.phone}</p></div>
                      <span className="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded-full font-semibold">{o.quantity}x</span>
                    </div>
                    <p className="text-sm text-gray-600 mb-2">{o.address}</p>
                    <div className="flex justify-between items-center">
                      <span className="text-xs text-gray-400">{o.product}</span>
                      <span className="text-xs text-gray-400">{formatDate(o.createdAt)}</span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* ---- PRODUCTS TAB ---- */}
        {tab === "products" && (
          <div>
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-lg font-bold text-gray-900">Senarai Produk ({products.length})</h2>
              <button onClick={() => { setEditProduct(null); setShowProductForm(true); }} className="bg-blue-600 text-white text-sm font-semibold px-4 py-2 rounded-xl hover:bg-blue-700">+ Tambah Produk</button>
            </div>

            {showProductForm && (
              <div className="mb-6">
                <ProductForm initial={editProduct || undefined} onSave={saveProduct} onCancel={() => { setShowProductForm(false); setEditProduct(null); }} loading={loading} />
              </div>
            )}

            {products.length === 0 ? (
              <p className="text-gray-500 text-center py-10">Tiada produk lagi. Klik "Tambah Produk".</p>
            ) : (
              <div className="space-y-3">
                {products.map((p) => (
                  <div key={p._id} className="bg-white rounded-xl p-5 shadow-sm border flex justify-between items-center">
                    <div>
                      <p className="font-bold text-gray-900">{p.name}</p>
                      <p className="text-sm text-gray-500">RM {p.price}</p>
                      <p className="text-xs text-gray-400 mt-1">{p.description?.slice(0, 80)}...</p>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => { setEditProduct(p); setShowProductForm(true); }} className="text-sm bg-gray-100 hover:bg-gray-200 px-3 py-1 rounded-lg">Edit</button>
                      <button onClick={() => deleteProduct(p._id)} className="text-sm bg-red-50 text-red-600 hover:bg-red-100 px-3 py-1 rounded-lg">Padam</button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* ---- LANDING PAGES TAB ---- */}
        {tab === "landing" && (
          <div>
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-lg font-bold text-gray-900">Landing Pages ({pages.length})</h2>
              <button onClick={() => { setEditLanding(null); setShowLandingEditor(true); }} className="bg-blue-600 text-white text-sm font-semibold px-4 py-2 rounded-xl hover:bg-blue-700">+ Landing Page Baru</button>
            </div>

            {showLandingEditor && (
              <div className="mb-6">
                <LandingEditor initial={editLanding} products={products} onSave={saveLanding} onCancel={() => { setShowLandingEditor(false); setEditLanding(null); }} loading={loading} />
              </div>
            )}

            {pages.length === 0 ? (
              <p className="text-gray-500 text-center py-10">Tiada landing page. Klik "Landing Page Baru".</p>
            ) : (
              <div className="space-y-3">
                {pages.map((lp) => (
                  <div key={lp._id} className="bg-white rounded-xl p-5 shadow-sm border flex justify-between items-center">
                    <div>
                      <div className="flex items-center gap-2">
                        <p className="font-bold text-gray-900">{lp.name}</p>
                        {lp.active && <span className="text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded-full font-semibold">Aktif</span>}
                      </div>
                      <p className="text-xs text-gray-400">/{lp.slug}</p>
                    </div>
                    <div className="flex gap-2">
                      {!lp.active && (
                        <button onClick={() => setActive(lp)} className="text-sm bg-green-50 text-green-600 hover:bg-green-100 px-3 py-1 rounded-lg">Aktifkan</button>
                      )}
                      <button onClick={() => { setEditLanding(lp); setShowLandingEditor(true); }} className="text-sm bg-gray-100 hover:bg-gray-200 px-3 py-1 rounded-lg">Edit</button>
                      <button onClick={() => deleteLanding(lp._id)} className="text-sm bg-red-50 text-red-600 hover:bg-red-100 px-3 py-1 rounded-lg">Padam</button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

