"use client";

import { useState, useEffect } from "react";
import Link from "next/link";

type LandingData = {
  _id: string;
  name: string;
  productId: string | null;
  sections: {
    hero: { badge: string; headline: string; subtext: string; ctaText: string; image: string };
    features: { title: string; html: string };
    testimonials: { title: string; html: string };
    cta: { headline: string; subtext: string; html: string };
  };
  whatsapp: string;
  product?: { name: string; price: number; description: string; benefits: string[]; image: string } | null;
};

export default function Home() {
  const [page, setPage] = useState<LandingData | null>(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem("admin_token");
    setIsAdmin(!!token);
    loadPage();
  }, []);

  const loadPage = async () => {
    try {
      const res = await fetch("/api/landing");
      const data = await res.json();
      if (data.success && data.page) setPage(data.page);
      else setPage(getFallback());
    } catch {
      setPage(getFallback());
    } finally {
      setLoading(false);
    }
  };

  if (loading || !page) {
    return <div className="min-h-screen flex items-center justify-center"><p>Loading...</p></div>;
  }

  const { sections: s, whatsapp } = page;
  const product = page.product;
  const heroImg = s.hero.image || (product?.image || "");
  const price = product?.price ? `RM ${product.price}` : "";
  const productId = page.productId || "";

  return (
    <>
      {/* HERO */}
      <section className="relative min-h-screen flex flex-col items-center justify-center text-center px-4 py-20 bg-gradient-to-b from-blue-50 to-white">
        <div className="max-w-3xl mx-auto">
          {s.hero.badge && (
            <span className="inline-block bg-blue-100 text-blue-700 text-sm font-semibold px-4 py-1 rounded-full mb-6">{s.hero.badge}</span>
          )}
          <div className="mb-6" dangerouslySetInnerHTML={{ __html: s.hero.headline }} />
          <div className="text-lg md:text-xl text-gray-600 mb-10" dangerouslySetInnerHTML={{ __html: s.hero.subtext }} />
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <Link href={`/checkout?product=${productId}`} className="inline-flex items-center justify-center px-8 py-4 rounded-full text-lg font-semibold bg-blue-600 text-white hover:bg-blue-700 shadow-lg">
              {s.hero.ctaText}
            </Link>
            <a href={`https://wa.me/${whatsapp}?text=Saya%20berminat`} target="_blank" rel="noopener noreferrer" className="inline-flex items-center justify-center px-8 py-4 rounded-full text-lg font-semibold bg-green-500 text-white hover:bg-green-600 shadow-lg">
              WhatsApp
            </a>
          </div>
          {heroImg && (
            <div className="mt-16">
              <img src={heroImg} alt="Produk" className="rounded-2xl w-full max-w-md mx-auto shadow-lg" />
            </div>
          )}
          {!heroImg && (
            <div className="mt-16">
              <div className="bg-gray-200 rounded-2xl w-full max-w-md mx-auto aspect-square flex items-center justify-center text-gray-400 text-sm">[ Gambar Produk ]</div>
            </div>
          )}
        </div>
      </section>

      {/* FEATURES */}
      {s.features.html && (
        <section className="py-20 px-4 bg-white">
          <div className="max-w-5xl mx-auto">
            {s.features.title && <h2 className="text-3xl md:text-4xl font-bold text-center text-gray-900 mb-4">{s.features.title}</h2>}
            <div className="prose max-w-none" dangerouslySetInnerHTML={{ __html: s.features.html }} />
          </div>
        </section>
      )}

      {/* PRODUCT INFO (if linked) */}
      {product && (
        <section className="py-20 px-4 bg-gray-50">
          <div className="max-w-5xl mx-auto">
            <div className="grid md:grid-cols-2 gap-12 items-center">
              <div>
                {product.image ? (
                  <img src={product.image} alt={product.name} className="rounded-2xl shadow-lg" />
                ) : (
                  <div className="bg-gray-200 rounded-2xl aspect-square flex items-center justify-center text-gray-400">[Gambar]</div>
                )}
              </div>
              <div>
                <h3 className="text-2xl font-bold text-gray-900 mb-2">{product.name}</h3>
                <p className="text-3xl font-extrabold text-blue-600 mb-6">RM {product.price}</p>
                <p className="text-gray-600 leading-relaxed mb-8">{product.description}</p>
                {product.benefits?.length > 0 && (
                  <ul className="space-y-3 mb-8">
                    {product.benefits.map((b: string, i: number) => <li key={i} className="text-gray-700">✅ {b}</li>)}
                  </ul>
                )}
              </div>
            </div>
          </div>
        </section>
      )}

      {/* TESTIMONIALS */}
      {s.testimonials.html && (
        <section className="py-20 px-4 bg-white">
          <div className="max-w-5xl mx-auto">
            {s.testimonials.title && <h2 className="text-3xl md:text-4xl font-bold text-center text-gray-900 mb-4">{s.testimonials.title}</h2>}
            <div className="prose max-w-none" dangerouslySetInnerHTML={{ __html: s.testimonials.html }} />
          </div>
        </section>
      )}

      {/* FINAL CTA */}
      <section className="py-20 px-4 bg-gradient-to-b from-white to-blue-50 text-center">
        <div className="max-w-2xl mx-auto">
          {s.cta.headline && <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">{s.cta.headline}</h2>}
          {s.cta.subtext && <p className="text-gray-600 mb-10 text-lg">{s.cta.subtext}</p>}
          {s.cta.html && <div className="mb-8" dangerouslySetInnerHTML={{ __html: s.cta.html }} />}
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <Link href={`/checkout?product=${productId}`} className="inline-flex items-center justify-center px-8 py-4 rounded-full text-lg font-semibold bg-blue-600 text-white hover:bg-blue-700 shadow-lg">
              {price ? `Beli Sekarang — ${price}` : "Beli Sekarang"}
            </Link>
            <a href={`https://wa.me/${whatsapp}?text=Saya%20nak%20order`} target="_blank" rel="noopener noreferrer" className="inline-flex items-center justify-center px-8 py-4 rounded-full text-lg font-semibold bg-green-500 text-white hover:bg-green-600 shadow-lg">
              Order Via WhatsApp
            </a>
          </div>
        </div>
      </section>

      {/* ADMIN FLOATING BUTTON */}
      {isAdmin && (
        <a href="/admin/dashboard" className="fixed bottom-6 right-6 bg-gray-900 text-white px-4 py-3 rounded-full shadow-xl text-sm font-semibold hover:bg-gray-800 z-50">
          Edit Page
        </a>
      )}
    </>
  );
}

function getFallback(): LandingData {
  return {
    _id: "",
    name: "Default",
    productId: null,
    sections: {
      hero: { badge: "Tawaran Terhad", headline: "<h1 class='text-4xl md:text-6xl font-extrabold text-gray-900'>Produk Yang Akan <span class='text-blue-600'>Mengubah Hidup Anda</span></h1>", subtext: "<p>Penyelesaian terbaik untuk masalah harian anda.</p>", ctaText: "Beli Sekarang", image: "" },
      features: { title: "Kenapa Produk Ini?", html: "<ul class='grid md:grid-cols-2 gap-4'><li class='text-gray-700'>✅ Kualiti premium</li><li class='text-gray-700'>✅ Hasil terbukti</li><li class='text-gray-700'>✅ Penghantaran percuma</li><li class='text-gray-700'>✅ Jaminan 30 hari</li></ul>" },
      testimonials: { title: "Apa Kata Pelanggan", html: "<p class='text-gray-600 text-center'>Ribuan pelanggan berpuas hati.</p>" },
      cta: { headline: "Sedia Untuk Cuba?", subtext: "Dapatkan sekarang.", html: "" },
    },
    whatsapp: "60123456789",
  };
}

