import { NextResponse } from "next/server";
import getClientPromise from "@/lib/mongodb";
import { ObjectId } from "mongodb";

export async function GET() {
  try {
    const client = await getClientPromise();
    const db = client.db("ecommerce");

    const page = await db.collection("landingpages").findOne({ active: true });

    if (!page) {
      return NextResponse.json({ success: false, message: "No active page" });
    }

    // Populate product if linked
    let product = null;
    if (page.productId) {
      product = await db.collection("products").findOne({ _id: new ObjectId(page.productId) });
    }

    return NextResponse.json({
      success: true,
      page: { ...page, product },
    });
  } catch (error: any) {
    return NextResponse.json({ success: false, message: error.message }, { status: 500 });
  }
}

