"use client";

import { useState, useEffect, Suspense } from "react";
import { useRouter, useSearchParams } from "next/navigation";

function CheckoutForm() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const productId = searchParams.get("product") || "";

  const [productName, setProductName] = useState("Produk Premium");
  const [productPrice, setProductPrice] = useState(99);
  const [whatsapp, setWhatsapp] = useState("60123456789");
  const [form, setForm] = useState({
    name: "",
    phone: "",
    address: "",
    product: "Produk Premium",
    quantity: 1,
  });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    fetch("/api/landing")
      .then((r) => r.json())
      .then((data) => {
        if (data.success && data.page) {
          if (data.page.whatsapp) setWhatsapp(data.page.whatsapp);
          if (data.page.product) {
            const p = data.page.product;
            setProductName(p.name);
            setProductPrice(p.price);
            setForm((f) => ({ ...f, product: p.name }));
          }
        }
      })
      .catch(() => {});
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: name === "quantity" ? Number(value) : value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    if (!form.name || !form.phone || !form.address) {
      setError("Sila isi semua ruangan.");
      return;
    }
    setLoading(true);
    try {
      const res = await fetch("/api/orders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...form, product: productName }),
      });
      const data = await res.json();
      if (data.success) {
        setSuccess(true);
        setTimeout(() => {
          const waMsg = encodeURIComponent(
            `Assalamualaikum, saya ${form.name}.\n\nSaya baru sahaja membuat pesanan:\n- Produk: ${productName}\n- Kuantiti: ${form.quantity}\n\nSila sahkan pesanan saya. Terima kasih.`
          );
          window.location.href = `https://wa.me/${whatsapp}?text=${waMsg}`;
        }, 2000);
      } else {
        setError(data.message || "Ralat tidak diketahui.");
      }
    } catch {
      setError("Ralat rangkaian.");
    } finally {
      setLoading(false);
    }
  };

  if (success) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center px-4 bg-gradient-to-b from-blue-50 to-white">
        <div className="max-w-md text-center">
          <div className="text-6xl mb-6">✅</div>
          <h1 className="text-3xl font-bold text-gray-900 mb-4">Pesanan Berjaya!</h1>
          <p className="text-gray-600 mb-8">Terima kasih {form.name}. Pesanan anda telah disimpan. Anda akan diarahkan ke WhatsApp...</p>
          <p className="text-sm text-gray-400">
            Jika tidak diarahkan,{" "}
            <a href={`https://wa.me/${whatsapp}?text=Saya%20${encodeURIComponent(form.name)}%20baru%20buat%20pesanan`} className="text-blue-600 underline">klik sini</a>
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col items-center justify-center px-4 py-20 bg-gradient-to-b from-blue-50 to-white">
      <div className="w-full max-w-lg">
        <h1 className="text-3xl font-bold text-gray-900 text-center mb-2">Buat Pesanan</h1>
        <p className="text-gray-500 text-center mb-8">Isi butiran di bawah untuk lengkapkan pesanan.</p>

        <form onSubmit={handleSubmit} className="bg-white rounded-2xl shadow-md border border-gray-100 p-8 space-y-5">
          <div className="bg-blue-50 rounded-xl p-4 flex justify-between items-center">
            <div>
              <p className="font-semibold text-gray-900">{productName}</p>
              <p className="text-sm text-gray-500">RM {productPrice}.00 seunit</p>
            </div>
            <div className="flex items-center gap-2">
              <button type="button" className="w-8 h-8 rounded-full bg-white border text-lg font-bold text-gray-600 hover:bg-gray-100" onClick={() => setForm((prev) => ({ ...prev, quantity: Math.max(1, prev.quantity - 1) }))}>−</button>
              <span className="font-bold text-gray-900 w-6 text-center">{form.quantity}</span>
              <button type="button" className="w-8 h-8 rounded-full bg-white border text-lg font-bold text-gray-600 hover:bg-gray-100" onClick={() => setForm((prev) => ({ ...prev, quantity: prev.quantity + 1 }))}>+</button>
            </div>
          </div>
          <p className="text-right font-bold text-blue-600">Jumlah: RM {(productPrice * form.quantity).toFixed(2)}</p>

          <div>
            <label htmlFor="name" className="block text-sm font-semibold text-gray-700 mb-1">Nama Penuh</label>
            <input type="text" id="name" name="name" value={form.name} onChange={handleChange} placeholder="Contoh: Ahmad bin Ali" className="w-full border border-gray-200 rounded-xl px-4 py-3 text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent" />
          </div>
          <div>
            <label htmlFor="phone" className="block text-sm font-semibold text-gray-700 mb-1">Nombor Telefon</label>
            <input type="tel" id="phone" name="phone" value={form.phone} onChange={handleChange} placeholder="Contoh: 0123456789" className="w-full border border-gray-200 rounded-xl px-4 py-3 text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent" />
          </div>
          <div>
            <label htmlFor="address" className="block text-sm font-semibold text-gray-700 mb-1">Alamat Penghantaran</label>
            <textarea id="address" name="address" value={form.address} onChange={handleChange} rows={3} placeholder="Contoh: 123, Jalan Bahagia, 50000 KL" className="w-full border border-gray-200 rounded-xl px-4 py-3 text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none" />
          </div>
          {error && <div className="bg-red-50 text-red-600 text-sm rounded-xl px-4 py-3 border border-red-100">{error}</div>}
          <button type="submit" disabled={loading} className="w-full bg-blue-600 text-white font-bold py-4 rounded-full text-lg hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-lg">
            {loading ? "Memproses..." : "Sahkan Pesanan"}
          </button>
        </form>
      </div>
    </div>
  );
}

export default function CheckoutPage() {
  return (
    <Suspense fallback={<div className="min-h-screen flex items-center justify-center">Loading...</div>}>
      <CheckoutForm />
    </Suspense>
  );
}

