import { NextRequest, NextResponse } from "next/server";
import getClientPromise from "@/lib/mongodb";
import { ObjectId } from "mongodb";

export async function GET(request: NextRequest) {
  try {
    const client = await getClientPromise();
    const db = client.db("ecommerce");
    const { searchParams } = new URL(request.url);
    const slug = searchParams.get("slug");

    let page;
    if (slug) {
      page = await db.collection("landingpages").findOne({ slug });
    } else {
      page = await db.collection("landingpages").findOne({ active: true });
    }

    if (!page) {
      return NextResponse.json({ success: false, message: "Page not found" });
    }

    let product = null;
    if (page.productId) {
      product = await db.collection("products").findOne({ _id: new ObjectId(page.productId) });
    }

    return NextResponse.json({ success: true, page: { ...page, product } });
  } catch (error: any) {
    return NextResponse.json({ success: false, message: error.message }, { status: 500 });
  }
}

